// ============================================
// PREPROCESS - WITH STATUS DETECTION FROM MESSAGE
// ============================================

const json = $input.item.json;

// Get the full message (includes SYSTEM_DATA + user query)
const fullMessage = json.message || json.ai_input_text || json.text || json.body || '';

// ============================================
// 1. EXTRACT USER QUERY
// ============================================
let actualUserMessage = '';

if (fullMessage.includes('[USER QUERY]')) {
  const parts = fullMessage.split('[USER QUERY]');
  actualUserMessage = parts[1] ? parts[1].trim() : '';
} else {
  actualUserMessage = fullMessage.trim();
}

// ============================================
// 2. PARSE SYSTEM_DATA
// ============================================
let userStatusInDB = '';
let isNewUser = false;
let greetingSent = false;

if (fullMessage.includes('[SYSTEM_DATA]')) {
  const statusMatch = fullMessage.match(/USER_STATUS_IN_DB:\s*(\w+)/i);
  if (statusMatch) {
    userStatusInDB = statusMatch[1];
  }

  const newUserMatch = fullMessage.match(/IS_NEW_USER:\s*(\w+)/i);
  if (newUserMatch) {
    isNewUser = newUserMatch[1].toLowerCase() === 'true';
  }

  const greetingMatch = fullMessage.match(/GREETING_SENT:\s*(\w+)/i);
  if (greetingMatch) {
    greetingSent = greetingMatch[1].toUpperCase() === 'YES';
  }
}

// ============================================
// 3. PROCESS MESSAGE
// ============================================
const message = actualUserMessage.toLowerCase();
const userPhone = json.userPhone || json.from || json.phone || json.user_wa || 'unknown';

// ============================================
// 4. DETECT STATUS FROM USER MESSAGE
// ============================================
let detectedStatusFromMessage = '';

// PARENT signals
if (message.match(/\b(orang\s*tua|ortu|ayah|ibu|bapak|mama|papa|anak\s*saya)\b/i)) {
  detectedStatusFromMessage = 'PARENT';
}
// STUDENT signals - COMPREHENSIVE LIST
else if (message.match(/\b(murid|saya\s*sendiri|saya\s*yang\s*mau|calon\s*murid|anaknya|aku\s*yang|aku\s*sendiri|saya\s*aja|aku\s*aja)\b/i)) {
  detectedStatusFromMessage = 'STUDENT';
}

// ============================================
// 5. DETECT GRADE & PROGRAM
//   FIX: SMA dipisah. Seniors KHUSUS kelas 12 (SMA 3).
//        SMA 10/11 (SMA 1/2) -> belum ada program yang cocok.
// ============================================
let grade = '';
let recommendedProgram = '';

if (message.match(/sd 6|kelas 6 sd|kelas 6(?!\s*smp)/i)) {
  grade = 'SD 6';
  recommendedProgram = 'Junior';
} else if (message.match(/smp 1|kelas 1 smp|kelas 7/i)) {
  grade = 'SMP 1';
  recommendedProgram = 'Junior';
} else if (message.match(/smp 2|kelas 2 smp|kelas 8/i)) {
  grade = 'SMP 2';
  recommendedProgram = 'Intermediate';
} else if (message.match(/smp 3|kelas 3 smp|kelas 9/i)) {
  grade = 'SMP 3';
  recommendedProgram = 'Intermediate';
} else if (message.match(/sma 3|kelas 3 sma|kelas 12/i)) {
  grade = 'SMA 12';
  recommendedProgram = 'Seniors';
} else if (message.match(/sma 1|sma 2|kelas 1 sma|kelas 2 sma|kelas 10|kelas 11/i)) {
  grade = 'SMA 10/11';
  recommendedProgram = '';   // Seniors khusus kelas 12 -> belum ada yang cocok
} else if (message.match(/sma|kelas.*sma/i)) {
  grade = 'SMA';
  recommendedProgram = '';   // kelas belum jelas -> jangan asumsi Seniors
}

// ============================================
// 6. DETECT REGISTRATION INTENT
// ============================================
const wantsToRegister = message.match(/daftar|mau ikut|tertarik|mau coba|mau daftar|link pendaftaran|link form|minta link/i) !== null;

// ============================================
// 6b. DETECT OUT-OF-SCOPE USER (di luar jenjang SMP-SMA)
//     mahasiswa / kuliah / kerja / sudah lulus / dewasa
// ============================================
let outOfScope = false;
if (message.match(/\b(mahasiswa|semester\s*\d+|lagi kuliah|sudah kuliah|udah kuliah|sarjana|magister|fresh graduate|gap year|karyawan|pegawai|sudah lulus|udah lulus|sudah kerja|udah kerja)\b/i)) {
  outOfScope = true;
}

// ============================================
// 6c. DETECT UNCLEAR / AMBIGUOUS SHORT REPLY (anti-loop)
// ============================================
const isGreetingLike = message.match(/^(hai|halo|hi|pagi|siang|sore|malam|makasih|thanks|terima kasih|ok|oke|sip|baik|👍|🙏)/i) !== null;
const unclearReply = (actualUserMessage.trim().length <= 4) && !grade && !detectedStatusFromMessage && !isGreetingLike && !wantsToRegister;

// ============================================
// 7. DETECT PERSUASION TRIGGERS
// ============================================
let persuasionMode = '';

if (message.match(/mau daftar|tertarik|boleh deh|mau coba|mau ikut|oke deh/i)) {
  persuasionMode = 'INTERESTED';
} else if (message.match(/nanti|pikir dulu|setelah ujian|belum sekarang|ragu|mikir|lihat dulu/i)) {
  persuasionMode = 'DEFER';
} else if (message.match(/\b(tf|transfer|bayar|mau bayar|sudah bayar|kirim bukti)\b/i)) {
  persuasionMode = 'PAYMENT';
}

// ============================================
// 8. DETECT TOPICS
// ============================================
const discussingProgram = message.match(/program|junior|intermediate|senior|batch/i) !== null;
const askingPrice = message.match(/berapa|biaya|harga|bayar|mahal|murah/i) !== null;
const askingBatch = message.match(/batch|kapan|mulai|jadwal|pendaftaran/i) !== null;

// ============================================
// 9. BUILD AI CONTEXT
//   Prinsip: blok ini HANYA suplai FAKTA deteksi + pointer yang
//   SELARAS dengan system message. Semua aturan gaya/persona tetap
//   milik system message (satu sumber kebenaran, anti-tabrakan).
// ============================================
let aiContext = '';

// Status context
if (userStatusInDB === 'EMPTY' && detectedStatusFromMessage) {
  aiContext += `CRITICAL: User baru mengungkap status (${detectedStatusFromMessage}). WAJIB pasang tag [USER_STATUS:${detectedStatusFromMessage}] di PALING AWAL output. `;
  if (detectedStatusFromMessage === 'PARENT') {
    aiContext += `Ke orang tua: langsung ke isi tanpa kata sapaan/vokatif, nada hangat tapi sopan. `;
  } else {
    aiContext += `Ke murid: boleh sapa 'kamu', nada suportif. `;
  }
} else if (userStatusInDB !== 'EMPTY') {
  aiContext += `User status: ${userStatusInDB}. `;
  if (userStatusInDB === 'PARENT') {
    aiContext += `Ke orang tua: langsung ke isi tanpa kata sapaan/vokatif, nada hangat-sopan. `;
  } else if (userStatusInDB === 'STUDENT') {
    aiContext += `Ke murid: boleh sapa 'kamu', nada suportif. `;
  }
} else {
  aiContext += `User status belum diketahui. Tanya dulu "orang tua atau anaknya" sebelum menjawab pertanyaan. `;
}

// Out-of-scope user (mahasiswa/kuliah/kerja) -> jangan tanya kelas SMP/SMA
if (outOfScope) {
  aiContext += `User kemungkinan di luar jenjang SMP-SMA (mahasiswa/kuliah/kerja). Sampaikan jujur program khusus siswa SMP-SMA, jadi belum ada yang cocok. JANGAN tanya kelas SMP/SMA. `;
}

// Anti-loop: balasan ambigu -> jangan ulang pertanyaan, tawarkan handoff
if (unclearReply) {
  aiContext += `Balasan user terlalu singkat/ambigu. JANGAN ulang pertanyaan yang sama. Kalau sebelumnya sudah bertanya hal yang sama, tawarkan bantuan langsung dari Sam: [TALK_TO_SAM]. `;
}

// Grade & program (skip nudge tanya kelas kalau user out-of-scope)
if (!outOfScope && grade && recommendedProgram) {
  aiContext += `User di ${grade} -> arahkan ke program ${recommendedProgram}. Catatan: SMP 2 = Intermediate (BUKAN Junior). Sebut HANYA program ${recommendedProgram}, jangan tawarkan tier program lain kecuali user tanya. `;
} else if (grade === 'SMA 10/11') {
  aiContext += `User di SMA kelas 10/11 -> belum ada program yang cocok untuk sekarang (Seniors khusus kelas 12). Sampaikan jujur dan arahkan ke opsi yang ada. `;
} else if (grade === 'SMA') {
  aiContext += `User SMA tapi kelas belum jelas -> tanya dulu kelas berapa (Seniors hanya untuk kelas 12). `;
}

// Registration intent (tunduk pada ATURAN BATCH di system message)
